DROP TABLE IF EXISTS `clinic_clinicaldocument`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `clinic_clinicaldocument` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `document_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` json NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `created_by_id` int NOT NULL,
  `patient_id` bigint NOT NULL,
  `payment_id` bigint DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `deleted_by_id` int DEFAULT NULL,
  `result_file` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payment_id` (`payment_id`),
  KEY `clinic_clinicaldocument_created_by_id_d6330ec3_fk_auth_user_id` (`created_by_id`),
  KEY `clinic_clinicaldocument_patient_id_f74c0cb6_fk_clinic_patient_id` (`patient_id`),
  KEY `clinic_clin_documen_7a0f06_idx` (`document_type`,`created_at`),
  KEY `clinic_clinicaldocument_deleted_by_id_c0517b0a_fk_auth_user_id` (`deleted_by_id`),
  KEY `clinic_clinicaldocument_deleted_at_3bec025f` (`deleted_at`),
  CONSTRAINT `clinic_clinicaldocument_created_by_id_d6330ec3_fk_auth_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_clinicaldocument_deleted_by_id_c0517b0a_fk_auth_user_id` FOREIGN KEY (`deleted_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `clinic_clinicaldocument_patient_id_f74c0cb6_fk_clinic_patient_id` FOREIGN KEY (`patient_id`) REFERENCES `clinic_patient` (`id`),
  CONSTRAINT `clinic_clinicaldocument_payment_id_bfddb89e_fk_clinic_payment_id` FOREIGN KEY (`payment_id`) REFERENCES `clinic_payment` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=316 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

