INSERT INTO `clinic_websitepagecontent` VALUES (4,'2026-06-30 06:09:09.435767','2026-09-13 04:41:00.200687','home','en','{\"slogan\": \"Health of mother and child; foundation of a healthy society.\", \"heroTitle\": \"Mother and child health, delivered with dignity and care.\", \"primaryCta\": \"Explore services\", \"heroEyebrow\": \"Non-profit community health center\", \"sloganLabel\": \"Center slogan\", \"featureCards\": [\"Maternal care\", \"Child care\", \"Laboratory\", \"Vaccination\"], \"secondaryCta\": \"Contact us\", \"audienceItems\": [\"Pregnant women and breastfeeding mothers\", \"Newborns, children, adolescents, and youth\", \"Low-income and vulnerable families\"], \"audienceTitle\": \"Care for families and vulnerable communities\", \"audienceEyebrow\": \"Who we serve\", \"heroDescription\": \"MCHC provides safe, accessible, and affordable health services for mothers, newborns, children, adults, and vulnerable families under the umbrella of Afghan Zamin Education and Development Assistance.\", \"featureDescription\": \"Compassionate, quality-focused service for families.\"}','http://mchc.site/media/website/pages/home/en/mother-child.webp',1,'website/pages/home/en/mother-child.webp'),(5,'2026-09-13 04:07:45.608421','2026-09-13 06:12:09.117178','home','fa','{\"slogan\": \"سلامت مادر و طفل؛ بنیاد جامعه سالم.\", \"heroTitle\": \"حمایت از صحت مادر و طفل با کرامت، کیفیت و مهربانی.\", \"primaryCta\": \"مشاهده خدمات\", \"heroEyebrow\": \"مرکز صحی جامعه‌محور\", \"sloganLabel\": \"شعار مرکز\", \"featureCards\": [\"صحت مادران\", \"صحت طفل\", \"لابراتوار\", \"واکسیناسیون\"], \"secondaryCta\": \"تماس با ما\", \"audienceItems\": [\"زنان حامله و مادران شیرده\", \"نوزادان، اطفال، نوجوانان و جوانان\", \"خانواده‌های کم‌درآمد و افراد نیازمند\"], \"audienceTitle\": \"رسیدگی به خانواده‌ها و اقشار آسیب‌پذیر\", \"audienceEyebrow\": \"گروه‌های هدف\", \"heroDescription\": \"مرکز حمایه صحت طفل و مادر تحت چتر مؤسسه خدمات تعلیمی و معاونت انکشافی افغان زمین خدمات صحی مصئون، قابل دسترس و مقرون‌به‌صرفه را برای مادران، نوزادان، اطفال، کهلان و خانواده‌های آسیب‌پذیر فراهم می‌سازد.\", \"featureDescription\": \"خدمات دلسوزانه و باکیفیت برای خانواده‌ها.\"}','',1,''),(6,'2026-09-13 04:11:53.690958','2026-09-13 04:12:09.111244','vision','fa','{\"title\": \"جامعه‌ای سالم با دسترسی عادلانه به خدمات باکیفیت\", \"eyebrow\": \"چشم‌انداز ما\", \"cardTitle\": \"\", \"highlight\": \"ما باور داریم که صحت مادر و طفل بنیاد خانواده نیرومندتر، جامعه سالم‌تر و آینده بهتر است.\", \"statement\": \"دستیابی به جامعه‌ای سالم که در آن همه مادران و کودکان به خدمات صحی با کیفیت، عادلانه و انسانی دسترسی داشته باشند.\"}','',1,''),(7,'2026-09-13 04:12:31.660817','2026-09-13 04:14:40.244835','mission','fa','{\"goals\": [\"بهبود شاخص‌های صحت مادر و طفل\", \"کاهش امراض و مرگ‌ومیر قابل پیشگیری\", \"حمایت از برنامه‌های ملی صحت\"], \"title\": \"خدمات صحی معیاری، مصئون، قابل دسترس و مقرون‌به‌صرفه\", \"eyebrow\": \"مأموریت ما\", \"cardTitle\": \"\", \"statement\": \"ارائه خدمات صحی معیاری، مصئون، قابل دسترس و مقرون‌به‌صرفه برای مادران، نوزادان، اطفال، کهلان و خانواده‌ها، با هدف ارتقای سلامت جامعه و حمایت از اقشار نیازمند، بدون انگیزه انتفاعی.\"}','',1,''),(8,'2026-09-13 04:15:44.257490','2026-09-13 04:15:44.257570','about','fa','{\"cards\": [{\"title\": \"معلومات عمومی\", \"paragraphs\": [\"مرکز حمایه صحت طفل و مادر یک مرکز صحی غیرانتفاعی است که برای ارائه خدمات صحی و بشردوستانه در بخش صحت مادر، نوزاد، طفل و خدمات OPD ایجاد شده است.\", \"این مرکز تحت چتر مؤسسه خدمات تعلیمی و معاونت انکشافی افغان زمین (AFZENDA) فعالیت می‌نماید؛ نهادی غیر دولتی و غیرانتفاعی که در وزارت اقتصاد ثبت و راجستر است.\"]}, {\"title\": \"پیشینه\", \"paragraphs\": [\"AFZENDA در بخش‌های خدمات اجتماعی، تعلیمی، صحت، محیط زیست، زراعت و آبیاری فعالیت دارد. به‌منظور پاسخ‌گویی به نیازهای روزافزون جامعه در بخش صحت و تسهیل دسترسی خانواده‌ها به خدمات صحی باکیفیت، MCHC در ناحیه ۱۷ شهر کابل ایجاد گردید.\", \"این مرکز با رویکرد بشردوستانه برای ارتقای صحت مادران، اطفال، کهلان و خانواده‌ها و تقویت رفاه اجتماعی فعالیت می‌کند.\"]}], \"title\": \"یک مرکز صحی غیرانتفاعی و جامعه‌محور تحت چتر مؤسسه خدمات تعلیمی و معاونت انکشافی افغان زمین\", \"values\": [\"رعایت اصول اسلامی و اخلاق حرفه‌ای\", \"احترام به کرامت انسانی و حقوق مریضان\", \"شفافیت و پاسخگویی\", \"عدالت و عدم تبعیض در ارائه خدمات\", \"کیفیت، مصئونیت و بهبود مستمر\", \"مسئولیت‌پذیری اجتماعی\", \"حمایت از اقشار آسیب‌پذیر\"], \"eyebrow\": \"درباره MCHC\"}','',1,''),(9,'2026-09-13 04:17:32.868979','2026-09-13 04:17:32.869059','home','ps','{\"slogan\": \"د مور او ماشوم روغتیا؛ د سالمې ټولنې بنسټ.\", \"heroTitle\": \"د مور او ماشوم روغتیا، په درناوي، کیفیت او پاملرنې سره.\", \"primaryCta\": \"خدمات وګورئ\", \"heroEyebrow\": \"ټولنې محوره روغتیايي مرکز\", \"sloganLabel\": \"د مرکز شعار\", \"featureCards\": [\"د میندو پاملرنه\", \"د ماشومانو پاملرنه\", \"لابراتوار\", \"واکسین\"], \"secondaryCta\": \"اړیکه ونیسئ\", \"audienceItems\": [\"حامله ښځې او شیدې ورکوونکې میندې\", \"نوي زېږېدلي ماشومان، ماشومان، تنکي ځوانان او ځوانان\", \"کم عاید لرونکې او زیانمنې کورنۍ\"], \"audienceTitle\": \"د کورنیو او زیانمنو ټولنو لپاره پاملرنه\", \"audienceEyebrow\": \"زموږ د خدمت ډلې\", \"heroDescription\": \"MCHC د AFZENDA تر چتر لاندې د میندو، نویو زېږېدلو ماشومانو، ماشومانو، لویانو او زیانمنو کورنیو لپاره خوندي، د لاسرسي وړ او ارزانه روغتیايي خدمات وړاندې کوي.\", \"featureDescription\": \"د کورنیو لپاره مهربانه او کیفیت لرونکي خدمات.\"}','',1,''),(10,'2026-09-13 04:23:54.751716','2026-09-13 04:30:41.715683','mission','en','{\"goals\": [\"Improve maternal and child health indicators\", \"Reduce preventable illness and mortality\", \"Support national health programs\"], \"title\": \"Safe, standard, accessible, and affordable health care\", \"eyebrow\": \"Our mission\", \"cardTitle\": \"\", \"statement\": \"To provide standard, safe, accessible, and affordable health services for mothers, newborns, children, adults, and families, with the goal of improving community health and supporting vulnerable groups without a profit motive.\"}','http://mchc.site/media/website/pages/mission/en/mother_and_child.jpg',1,'website/pages/mission/en/mother_and_child_S6pYNWy.jpg'),(11,'2026-09-13 04:24:09.911415','2026-09-13 04:35:49.713931','vision','en','{\"title\": \"A healthy society with fair access to quality care\", \"eyebrow\": \"Our vision\", \"cardTitle\": \"\", \"highlight\": \"We believe mother and child health is the foundation of a stronger family, a stronger community, and a healthier future.\", \"statement\": \"To reach a healthy society where all mothers and children have access to quality, fair, and humane health services.\"}','',1,'website/pages/vision/en/mother_and_child.jpg'),(12,'2026-09-13 04:28:05.345397','2026-09-13 04:29:00.069360','about','en','{\"cards\": [{\"title\": \"General information\", \"paragraphs\": [\"MCHC is a non-profit health center established to provide health and humanitarian services in maternal health, newborn care, child health, and OPD services.\", \"The center operates under the Afghan Zemina Educational Services and Development Assistance Organization (AFZENDA), a non-governmental and non-profit organization registered with the Ministry of Economy.\"]}, {\"title\": \"Background\", \"paragraphs\": [\"AFZENDA works in social services, education, health, environment, agriculture, and irrigation. To respond to growing community health needs and improve family access to quality care, MCHC was established in District 17 of Kabul City.\", \"The center works with a humanitarian approach to improve the health of mothers, children, adults, and families while supporting social welfare.\"]}], \"title\": \"A community-centered non-profit clinic under AFZENDA\", \"values\": [\"Islamic principles and professional ethics\", \"Respect for human dignity and patient rights\", \"Transparency and accountability\", \"Fair, non-discriminatory service delivery\", \"Quality, safety, and continuous improvement\", \"Social responsibility\", \"Support for vulnerable families\"], \"eyebrow\": \"About MCHC\"}','http://mchc.site/media/website/pages/about/en/mother_and_child.jpg',1,'website/pages/about/en/mother_and_child.jpg'),(13,'2026-09-13 04:55:47.751399','2026-09-14 08:31:55.610127','contact','ps','{\"title\": \"له د مور او ماشوم د روغتیا ملاتړ مرکزسره اړیکه ونیسئ\", \"fields\": [{\"label\": \"نوم\", \"value\": \"د مور او ماشوم د روغتیا مرکز (MCHC)\"}, {\"label\": \"مسئوله اداره\", \"value\": \"د افغان زمین د تعلیمي خدمتونو او انکشافي مرستو مؤسسه\"}, {\"label\": \"پته\", \"value\": \"ناحیه ۱۷، د مارشال فهیم څلوېښت متره سړک، 11 کوڅه\"}, {\"label\": \"تلیفون\", \"value\": \"٠٧٠٥٠٠٠٥٠٠\"}], \"eyebrow\": \"اړیکه ونیسئ\", \"placeholders\": {\"name\": \"ستاسو نوم\", \"submit\": \"پیغام ولېږئ\", \"contact\": \"تلیفون یا ایمیل\", \"message\": \"پیغام\"}, \"clinicCardTitle\": \"د مرکز معلومات\", \"messageCardTitle\": \"پیغام واستوئ\"}','',1,''),(14,'2026-09-13 04:56:15.404345','2026-09-13 04:56:15.404400','vision','ps','{\"title\": \"سالمه ټولنه چې کیفیت لرونکو خدماتو ته عادلانه لاسرسی ولري\", \"eyebrow\": \"زموږ لیدلوری\", \"cardTitle\": \"\", \"highlight\": \"موږ باور لرو چې د مور او ماشوم روغتیا د پیاوړې کورنۍ، سالمې ټولنې او ښه راتلونکي بنسټ دی.\", \"statement\": \"داسې سالمې ټولنې ته رسېدل چې ټولې میندې او ماشومان کیفیت لرونکو، عادلانه او انساني روغتیايي خدماتو ته لاسرسی ولري.\"}','',1,''),(15,'2026-09-13 04:56:44.937209','2026-09-13 04:56:44.937342','mission','ps','{\"goals\": [\"د مور او ماشوم د روغتیا شاخصونو ښه کول\", \"د مخنیوي وړ ناروغیو او مړینې کمول\", \"د ملي روغتیايي پروګرامونو ملاتړ\"], \"title\": \"معیاري، خوندي، د لاسرسي وړ او ارزانه روغتیايي خدمات\", \"eyebrow\": \"زموږ ماموریت\", \"cardTitle\": \"\", \"statement\": \"د میندو، نویو زېږېدلو ماشومانو، ماشومانو، لویانو او کورنیو لپاره معیاري، خوندي، د لاسرسي وړ او ارزانه روغتیايي خدمات وړاندې کول، د ټولنې د روغتیا د لوړولو او د اړمنو ډلو د ملاتړ په موخه، پرته له انتفاعي انګېزې.\"}','',1,''),(16,'2026-09-13 04:58:11.493675','2026-09-14 07:48:22.673822','contact','en','{\"title\": \"Visit or contact MCHC\", \"fields\": [{\"label\": \"Name\", \"value\": \"Mother and Child Health Support Center (MCHC)\"}, {\"label\": \"Operating organization\", \"value\": \"Afghan Zamin Educational and Development Assistance Organization\"}, {\"label\": \"Location\", \"value\": \"District 17, 40-Meter Street Of Marshal Fahim, Alley 11\"}, {\"label\": \"Phone\", \"value\": \"0705000500\"}], \"eyebrow\": \"Contact us\", \"placeholders\": {\"name\": \"Your name\", \"submit\": \"Submit message\", \"contact\": \"Phone or email\", \"message\": \"Message\"}, \"clinicCardTitle\": \"Clinic information\", \"messageCardTitle\": \"Send a message\"}','',1,''),(17,'2026-09-13 05:07:34.324381','2026-09-14 07:49:27.290101','contact','fa','{\"title\": \"با مرکز حمایه صحت طفل و مادر در تماس شوید\", \"fields\": [{\"label\": \"نام\", \"value\": \"مركز صحي حمايه طفل و مادر (MCHC)\"}, {\"label\": \"نهاد مسئول\", \"value\": \"مؤسسه خدمات تعلیمی و معاونت انکشافی افغان زمین\"}, {\"label\": \"آدرس\", \"value\": \"ناحيه ١٧ ، سرك چهل متره مارشال فهيم كوچه ١١\"}, {\"label\": \"تلیفون\", \"value\": \"٠٧٠٥٠٠٠٥٠٠\"}], \"eyebrow\": \"تماس با ما\", \"placeholders\": {\"name\": \"نام شما\", \"submit\": \"ارسال پیام\", \"contact\": \"شماره تماس یا ایمیل\", \"message\": \"پیام\"}, \"clinicCardTitle\": \"معلومات مرکز\", \"messageCardTitle\": \"ارسال پیام\"}','',1,''),(18,'2026-09-13 11:32:49.999023','2026-09-13 11:33:17.594547','news','en','{\"next\": \"Next\", \"empty\": \"No news has been published yet.\", \"error\": \"News could not be loaded right now.\", \"title\": \"News\", \"loading\": \"Loading news...\", \"previous\": \"Previous\", \"subtitle\": \"Latest news and updates from Mother and Child Health Support Center\", \"placeholder\": \"MCHC News\"}','',1,''),(19,'2026-09-13 11:33:33.649659','2026-09-13 11:33:33.649706','news','fa','{\"next\": \"بعدی\", \"empty\": \"هنوز خبری منتشر نشده است.\", \"error\": \"اخبار فعلاً بارگذاری نمی‌شود.\", \"title\": \"اخبار \", \"loading\": \"در حال بارگذاری اخبار...\", \"previous\": \"قبلی\", \"subtitle\": \"تازه‌ترین اخبار و مطالب مرکز حمایه صحت طفل و مادر\", \"placeholder\": \"اخبار MCHC\"}','',1,''),(20,'2026-09-13 11:34:08.904074','2026-09-13 11:35:08.459087','news','ps','{\"next\": \"بل\", \"empty\": \"تر اوسه کوم خبر نه دی خپور شوی.\", \"error\": \"اوس مهال خبرونه نه شي پورته کېدای.\", \"title\": \"خبرونه\", \"loading\": \"خبرونه پورته کېږي...\", \"previous\": \"مخکینی\", \"subtitle\": \"د مور او ماشوم د روغتیا ملاتړ مرکز وروستي خبرونه او لیکنې\", \"placeholder\": \"د MCHC خبرونه\"}','',1,'');
